INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(25501, 'John 12:48', 'John', 12, 48, '&nbsp;خو څوک چې ما نۀ منى او زما پېغام نۀ قبلوى، د هغۀ دپاره يو منصف شته، يعنې، زما هغه کلام چې ما کړے دے، هغه به په ورځ د آخرت د هغۀ عدالت وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25502, 'John 12:49', 'John', 12, 49, '&nbsp;زۀ په خپل اختيار خبرې نۀ کوم خو پلار چې زۀ يې رالېږلے يم هغۀ ما ته حُکم کړے دے چې څۀ ووايم او څنګه يې ووايم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25503, 'John 12:50', 'John', 12, 50, '&nbsp;او زۀ خبر يم چې د هغۀ حُکم د تل عُمرى ژوندون ورکوى، نو ځکه څۀ چې پلار ما ته فرمائيلى دى، هم هغه څۀ زۀ وايم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25504, 'John 13:1', 'John', 13, 1, '&nbsp;د فسح د اختر نه مخکښې عيسىٰ ته معلومه شوه چې د دُنيا نه د هغۀ د جدايۍ وخت رانزدې شوے دے او هغه به خپل پلار ته ورشى. او د خپلو مريدانو سره يې په دې دُنيا کښې مينه وه، او تر آخره وخته پورې يې ورسره مينه وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25505, 'John 13:2', 'John', 13, 2, '&nbsp;د ماښام د روټۍ وخت وو، او اِبليس د مخکښې نه د شمعون اِسکريوتى د زوئ يهوداه په زړۀ کښې دا خيال اچولے وو چې په عيسىٰ مُخبرى وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25506, 'John 13:3', 'John', 13, 3, '&nbsp;او عيسىٰ پوهه وو چې پلار هغۀ له د هر څۀ اختيار ورکړے دے او چې هغه د خُدائ پاک نه راغلے دے او خُدائ پاک له واپس روان دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25507, 'John 13:4', 'John', 13, 4, '&nbsp;نو هغه د روټۍ نه پاڅېدو، خپل څادر يې يو طرف ته کېښودو، يوه توليه يې راواخسته او د ملا نه يې تاو کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25508, 'John 13:5', 'John', 13, 5, '&nbsp;بيا هغۀ په يو لوښى کښې اوبۀ واچولې او د خپلو مريدانو په پښو وينځلو يې شروع وکړه او په هغه توليه يې وچولې چې د ځان نه يې تاو کړې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25509, 'John 13:6', 'John', 13, 6, '&nbsp;کله چې هغه شمعون پطروس ته راورسېدو نو پطروس هغۀ ته ووئيل چې، ”مالِکه، تۀ به زما پښې وينځې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25510, 'John 13:7', 'John', 13, 7, '&nbsp;عيسىٰ جواب ورکړو، ”څۀ چې زۀ کوم، تۀ اوس په دې نۀ پوهېږې خو وروستو به پوهه شې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25511, 'John 13:8', 'John', 13, 8, '&nbsp;پطروس هغۀ ته ووئيل، ”زۀ به تاسو هيڅکله پرې نۀ ږدم چې زما پښې ووينځې.“ عيسىٰ جواب ورکړو چې، ”ترڅو چې زۀ تا ونۀ وينځم نو تۀ به زما مريد نۀ يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25512, 'John 13:9', 'John', 13, 9, '&nbsp;شمعون پطروس هغۀ ته ووئيل، ”بيا نو مالِکه، نۀ يواځې زما پښې بلکې لاسونه او سر مې هم ووينځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25513, 'John 13:10', 'John', 13, 10, '&nbsp;عيسىٰ هغۀ ته وفرمائيل، ”چا چې لامبلى وى هغۀ ته د پښو د وينځلو نه علاوه نور حاجت نشته بلکې هغه ټول پاک دے، او تاسو پاک يئ خو ټول نه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25514, 'John 13:11', 'John', 13, 11, '&nbsp;ځکه چې عيسىٰ ته معلومه وه چې څوک به په هغۀ مُخبرى کوى نو په دې وجه هغۀ وفرمائيل چې، تاسو ټول پاک نۀ يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25515, 'John 13:12', 'John', 13, 12, '&nbsp;د هغوئ د پښو وينځلو نه پس، هغۀ خپل څادر راواخستو او کښېناستو او د هغوئ نه يې تپوس وکړو، ”تاسو په دې پوهه شوئ چې ما تاسو سره څۀ وکړل؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25516, 'John 13:13', 'John', 13, 13, '&nbsp;تاسو ما ته اُستاذ او مالِک وايئ او دا ټيک وايئ ځکه چې زۀ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25517, 'John 13:14', 'John', 13, 14, '&nbsp;نو کۀ ما ستاسو مالِک او اُستاذ ستاسو پښې ووينځلې نو په تاسو هم لازم دى چې د يو بل پښې ووينځئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25518, 'John 13:15', 'John', 13, 15, '&nbsp;ما ستاسو دپاره يو مِثال قائم کړے دے، چې تاسو به هم هغه شان کوئ، څنګه چې ما تاسو سره کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25519, 'John 13:16', 'John', 13, 16, '&nbsp;زۀ تاسو ته رښتيا وايم چې يو نوکر د خپل مالِک نه لوئ نۀ وى او نۀ پېغام وړونکے د رالېږونکى نه لوئ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25520, 'John 13:17', 'John', 13, 17, '&nbsp;اوس تاسو په دې خبره پوهه شوئ نو تاسو بختور يئ کۀ چرې عمل پرې وکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25521, 'John 13:18', 'John', 13, 18, '&nbsp;زۀ ستاسو ټولو په حقله نۀ وايم، څوک چې ما غوره کړى دى هغوئ زۀ پېژنم. خو چې د صحيفې دا خبره پوره شى چې، ”نو هغه چا چې روټۍ به يې ما سره خوړه هم هغه زما خلاف شولو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25522, 'John 13:19', 'John', 13, 19, '&nbsp;زۀ تاسو ته اوس د هغه واقعې د پېښېدو نه مخکښې دا وايم د دې دپاره چې کله هغه پېښه شى نو چې تاسو ايمان راوړئ چې مسيح هم زۀ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25523, 'John 13:20', 'John', 13, 20, '&nbsp;زۀ تاسو ته رښتيا وايم څوک چې زما يو پېغام وړونکے قبول کړى هغوئ ما قبلوى او څوک چې ما قبول کړى نو هغه قبلوى چا چې زۀ رالېږلے يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25524, 'John 13:21', 'John', 13, 21, '&nbsp;د دې وئيلو نه پس عيسىٰ روح کښې سخت پرېشانه شو او وې وفرمائيل، ”زۀ درته رښتيا وايم چې په تاسو کښې به يو زما مُخبرى کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25525, 'John 13:22', 'John', 13, 22, '&nbsp;مريدانو يو بل ته وکتل او شکمن شول چې دے دا د چا په حقله خبرې کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25526, 'John 13:23', 'John', 13, 23, '&nbsp;په هغوئ کښې يو مريد چې عيسىٰ ورسره مينه کوله، د عيسىٰ سره جُخت ناست وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25527, 'John 13:24', 'John', 13, 24, '&nbsp;نو شمعون پطروس هغۀ ته اِشاره وکړه او ورته يې ووئيل چې، ”تپوس ترې وکړه چې هغه دا څوک يادوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25528, 'John 13:25', 'John', 13, 25, '&nbsp;نو هغه مريد عيسىٰ ته سر ورنزدې کړو او تپوس يې ترې وکړو، ”مالِکه، دا څوک دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25529, 'John 13:26', 'John', 13, 26, '&nbsp;عيسىٰ جواب ورکړو، ”دا هغه څوک دے چې زۀ ورته د روټۍ دا ټُکړه په تالى کښې لمده کړم او ور يې کړم.“ بيا هغۀ د روټۍ ټُکړه لمده کړه او د شمعون اِسکريوتى زوئ يهوداه له يې ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25530, 'John 13:27', 'John', 13, 27, '&nbsp;د روټۍ د ټکړې خوړلو نه پس شېطان په هغۀ کښې ورننوتو. عيسىٰ هغۀ ته وفرمائيل، ”څۀ چې کوې، زر يې وکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25531, 'John 13:28', 'John', 13, 28, '&nbsp;څوک چې روټۍ ته ناست وُو د هغوئ نه يو کس هم په دې پوهه نۀ شو چې هغۀ ولې دۀ ته داسې وفرمائيل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25532, 'John 13:29', 'John', 13, 29, '&nbsp;ځينو دا ګُمان وکړو چې يهوداه سره تيلۍ ده، نو عيسىٰ هغۀ ته دا وفرمائيل چې اختر له چې څۀ په کار دى هغه واخله يا دا چې غريبانانو له څۀ ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25533, 'John 13:30', 'John', 13, 30, '&nbsp;د نوړۍ اخستو نه پس سمدستى يهوداه بهر ووتو. او دا توره شپه وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25534, 'John 13:31', 'John', 13, 31, '&nbsp;کله چې يهوداه بهر لاړو نو عيسىٰ وفرمائيل، ”اوس اِبن آدم خپله لوئى وموندله او خُدائ پاک په هغۀ کښې لوئى وموندله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25535, 'John 13:32', 'John', 13, 32, '&nbsp;کۀ خُدائ پاک په هغۀ کښې لوئى وموندله، نو خُدائ پاک به هم هغۀ ته په خپل ځان کښې لوئى ورکړى او هغۀ ته به زر لوئى ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25536, 'John 13:33', 'John', 13, 33, '&nbsp;زما بچو، زۀ به د لږ وخت دپاره تاسو سره يم. بيا به تاسو ما لټوئ، او څنګه چې ما يهوديانو ته وفرمائيل، نو دغه شان اوس تاسو ته هم وايم، چرته چې زۀ ځم هلته تاسو نۀ شئ راتلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25537, 'John 13:34', 'John', 13, 34, '&nbsp;زۀ تاسو له يو نوے حُکم درکوم چې د يو بل سره مينه کوئ. لکه چې ما تاسو سره مينه کړې ده نو دغه شان تاسو هم د يو بل سره مينه کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25538, 'John 13:35', 'John', 13, 35, '&nbsp;کۀ تاسو د يو بل سره مينه کوئ نو بيا به ټول خلق په دې پوهه شى چې تاسو زما مريدان يئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25539, 'John 13:36', 'John', 13, 36, '&nbsp;شمعون پطروس هغۀ ته ووئيل، ”مالِکه، تۀ چرته ځې؟“ عيسىٰ جواب ورکړو، ”چرته چې زۀ ځم، تۀ اوس ما پسې هلته نۀ شې راتلے خو وروستو به راشې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25540, 'John 13:37', 'John', 13, 37, '&nbsp;پطروس هغۀ ته ووئيل، ”مالِکه، زۀ اوس ولې نۀ شم درتلے؟ زۀ به خپل ځان په تا قربان کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25541, 'John 13:38', 'John', 13, 38, '&nbsp;عيسىٰ جواب ورکړو، ”تۀ به په رښتيا خپل ځان په ما قربان کړې څۀ؟ زۀ تا ته رښتيا وايم چې نن به تۀ د چرګ د بانګ نه وړاندې درې ځله زما نه اِنکارى شې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25542, 'John 14:1', 'John', 14, 1, '&nbsp;”خپل زړونه مۀ پرېشانه کوئ، په خُدائ پاک ايمان ساتئ، او په ما هم ايمان ساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25543, 'John 14:2', 'John', 14, 2, '&nbsp;زما د پلار په کور کښې د اوسېدو ډېر ځايونه دى. کۀ چرې داسې نۀ وے نو بيا به ما تاسو ته دا وئيلى وُو څۀ چې زۀ ځم چې تاسو دپاره ځائ تيار کړم؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25544, 'John 14:3', 'John', 14, 3, '&nbsp;او کۀ زۀ لاړ شم او تاسو له ځائ تيار کړم نو زۀ به په خپله بيا راشم او تاسو به د ځان سره بوځم، نو چې چرته زۀ يم هلته به تاسو هم يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25545, 'John 14:4', 'John', 14, 4, '&nbsp;او تاسو ته د هغې لارې پته ده کوم ځائ ته چې زۀ روان يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25546, 'John 14:5', 'John', 14, 5, '&nbsp;توما هغۀ ته ووئيل، ”مالِکه، مونږ ته پته نشته چې تۀ چرته روان يې، نو مونږ ته د لارې څۀ پته ده؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25547, 'John 14:6', 'John', 14, 6, '&nbsp;عيسىٰ هغۀ ته وفرمائيل، ”زۀ لار يم، زۀ حق يم او زۀ ژوندون يم. هيڅوک هم زما د وسيلې نه بغېر پلار له نۀ شى راتلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25548, 'John 14:7', 'John', 14, 7, '&nbsp;کۀ تاسو زۀ پېژندلے نو تاسو به زما پلار هم پېژندلو. د هم اوس نه تاسو هغه پېژنئ او ليدلے مو دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25549, 'John 14:8', 'John', 14, 8, '&nbsp;فيليپوس هغۀ ته ووئيل، ”مالِکه، مونږ ته پلار وښايه نو مونږ به مطمئن شُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25550, 'John 14:9', 'John', 14, 9, '&nbsp;عيسىٰ جواب ورکړو چې، ”فيليپوسه، تا سره زۀ د دومره مودې نه يم او بيا مې هم نۀ پېژنې څۀ؟ چا چې زۀ ليدلے يم هغۀ پلار هم ليدلے دے، نو بيا تۀ څنګه وائې چې مونږ ته پلار وښايه؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25551, 'John 14:10', 'John', 14, 10, '&nbsp;په دې ستاسو باور نشته چې زۀ په پلار کښې يم او پلار په ما کښې دے؟ زۀ چې کومې خبرې تاسو ته کوم هغه زۀ د خپل ځان نه نۀ کوم، خو دا پلار دے چې په ما کښې اوسى او زما په وسيله خپل کار کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25552, 'John 14:11', 'John', 14, 11, '&nbsp;په ما يقين وکړئ چې زۀ پلار کښې يم او پلار په ما کښې دے خو کۀ په ما يقين نۀ کوئ، نو بيا په ما د دې کارونو په وجه باور وکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25553, 'John 14:12', 'John', 14, 12, '&nbsp;زۀ تاسو ته رښتيا وايم، څوک چې په ما ايمان راوړى هغه به هم هغه کارونه کوى لکه چې زۀ يې کوم، او هغه به د دې نه هم لوئ کارونه کوى ځکه چې زۀ پلار له روان يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25554, 'John 14:13', 'John', 14, 13, '&nbsp;تاسو چې څۀ هم زما په نوم وغواړئ زۀ به هغه وکړم نو چې د پلار لوئى په زوئ کښې څرګنده شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25555, 'John 14:14', 'John', 14, 14, '&nbsp;کۀ تاسو زما په نوم ما نه څۀ هم وغواړئ زۀ به يې وکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25556, 'John 14:15', 'John', 14, 15, '&nbsp;کۀ تاسو ما سره مينه کوئ نو تاسو به زما په حُکمونو عمل کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25557, 'John 14:16', 'John', 14, 16, '&nbsp;او زۀ به پلار ته خواست وکړم چې تاسو ته بل مددګار درکړى چې تاسو سره به مدام وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25558, 'John 14:17', 'John', 14, 17, '&nbsp;هغه د حق روح دے، کوم چې دُنيا نۀ قبلوى ځکه چې دُنيا نۀ خو هغه وينى او نۀ يې پېژنى. خو تاسو هغه پېژنئ ځکه چې هغه تاسو سره اوسى او هغه به په تاسو کښې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25559, 'John 14:18', 'John', 14, 18, '&nbsp;زۀ به تاسو يتيمان نۀ پرېږدم، زۀ تاسو له واپس راځم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25560, 'John 14:19', 'John', 14, 19, '&nbsp;لږ وخت پس به دُنيا ما نور ونۀ وينى خو تاسو به مې وينئ. ځکه چې زۀ ژوندے يم نو تاسو به هم ژوندى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25561, 'John 14:20', 'John', 14, 20, '&nbsp;په هغه ورځ به تاسو پوهه شئ چې زۀ په خپل پلار کښې يم او تاسو په ما کښې يئ او زۀ په تاسو کښې يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25562, 'John 14:21', 'John', 14, 21, '&nbsp;څوک چې زما حُکمونه منى او په هغې عمل کوى نو دا هغه خلق دى چې ما سره مينه کوى. او څوک چې ما سره مينه کوى زما پلار به ورسره مينه وکړى او زۀ به هم د هغۀ سره مينه کوم او خپل ځان به ورته ښکاره کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25563, 'John 14:22', 'John', 14, 22, '&nbsp;بل يهوداه ترې تپوس وکړو، ”مالِکه، دا څۀ وجه ده چې تۀ به صرف مونږ ته ځان ښکاره کړې او نورې دُنيا ته نه؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25564, 'John 14:23', 'John', 14, 23, '&nbsp;عيسىٰ ورته جواب ورکړو، ”څوک چې زما سره مينه کوى، هغوئ به زما په کلام عمل کوى او زما پلار به د هغوئ سره مينه کوى، او زۀ او پلار به هغوئ ته ورشو او د هغوئ سره به اوسو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25565, 'John 14:24', 'John', 14, 24, '&nbsp;څوک چې ما سره مينه نۀ کوى هغه زما په کلام عمل نۀ کوى، او دا کلام چې تاسو يې اورئ دا زما نۀ دے بلکې دا د پلار کلام دے چا چې زۀ رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25566, 'John 14:25', 'John', 14, 25, '&nbsp;ترڅو چې لا زۀ تاسو سره يم ما تاسو ته دا هر څۀ وفرمائيل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25567, 'John 14:26', 'John', 14, 26, '&nbsp;خو مددګار يعنې روحُ القُدس چې پلار به يې زما په نوم راولېږى، هغه به تاسو ته هر څۀ وښائى او درته به هغه هر څۀ دريادوى، چې ما تاسو ته فرمائيلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25568, 'John 14:27', 'John', 14, 27, '&nbsp;زۀ تاسو ته سکون پرېږدم، زما خپل سکون، هغه چې دُنيا يې نۀ شى ورکولے. نو مۀ پرېشانه کېږئ او مۀ يرېږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25569, 'John 14:28', 'John', 14, 28, '&nbsp;تاسو واورېدل چې ما درته وفرمائيل، زۀ درنه روان يم او زۀ بيا تاسو له واپس راځم. کۀ چرې تاسو ما سره مينه کوئ نو تاسو به په دې خوشحاله شئ چې زۀ پلار له روان يم ځکه چې پلار زما نه لوئ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25570, 'John 14:29', 'John', 14, 29, '&nbsp;ما تاسو ته اوس د دې د پېښېدو نه مخکښې دا وفرمائيل نو چې کله دا پېښ شى نو تاسو به ايمان راوړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25571, 'John 14:30', 'John', 14, 30, '&nbsp;زۀ به پس د دې نه تاسو سره ډيرې خبرې ونۀ کړم ځکه چې د دې دُنيا سردار يعنې شېطان راتلونکے دے. خو د هغۀ په ما هيڅ اختيار نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25572, 'John 14:31', 'John', 14, 31, '&nbsp;زۀ هغه کار کوم چې پلار څنګه حُکم کړے دے نو ځکه چې دُنيا په دې پوهه شى چې زۀ د پلار سره مينه کوم. نو راځئ چې د دې ځائ نه ځو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25573, 'John 15:1', 'John', 15, 1, '&nbsp;”زۀ د انګور اصلى بوټے يم او زما پلار باغوان دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25574, 'John 15:2', 'John', 15, 2, '&nbsp;هغه زما نه هره هغه څانګه پرې کوى چې مېوه نۀ نيسى او هره څانګه چې مېوه نيسى په هغې کښې قينچى کوى چې نوره زياته مېوه ونيسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25575, 'John 15:3', 'John', 15, 3, '&nbsp;د هغه کلام په ذريعه کوم چې ما تاسو ته اورولے دے تاسو خو پاک او صفا شوى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25576, 'John 15:4', 'John', 15, 4, '&nbsp;په ما کښې اوسئ لکه چې زۀ په تاسو کښې اوسېږم. لکه څنګه چې يوه څانګه يواځې مېوه نۀ شى نيولے، ترڅو چې هغه د انګور د بوټى سره پيوند نۀ وى، دغسې تاسو هم مېوه نۀ شئ نيولے ترڅو چې تاسو په ما کښې نۀ اوسئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25577, 'John 15:5', 'John', 15, 5, '&nbsp;زۀ د انګور بوټے يم او تاسو زما څانګې يئ. څوک چې په ما کښې اوسى او زۀ په هغوئ کښې نو هغوئ ډېره مېوه نيسى، ځکه چې زما نه بغېر تاسو هيڅ نۀ شئ کولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25578, 'John 15:6', 'John', 15, 6, '&nbsp;هر څوک چې په ما کښې نۀ اوسى هغه به لکه د بې‌کاره څانګې په شان ګزار کړے شى، او اوچ به شى، او دغه شان اوچې څانګې يو ځائ ته راټوليږى او په اور کښې سوزولے کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25579, 'John 15:7', 'John', 15, 7, '&nbsp;کۀ چرې تاسو په ما کښې اوسئ او زما خبرې په تاسو کښې اوسى نو څۀ چې تاسو غواړئ هغه به تاسو له درکړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25580, 'John 15:8', 'John', 15, 8, '&nbsp;نو چې کله تاسو ډېره مېوه نيسئ نو په دې سره زما اصلى مريدان يئ او په دې سره زما پلار ته لوئى ملاويږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25581, 'John 15:9', 'John', 15, 9, '&nbsp;څنګه چې پلار ما سره مينه کړې ده نو دغه شان زۀ تاسو سره مينه کوم. زما په مينه کښې اوسئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25582, 'John 15:10', 'John', 15, 10, '&nbsp;کۀ چرې تاسو زما په حُکمونو عمل کوئ نو تاسو به زما په مينه کښې اوسېږئ لکه څنګه چې ما د خپل پلار په حُکمونو عمل کړے دے او د هغۀ په مينه کښې اوسېږم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25583, 'John 15:11', 'John', 15, 11, '&nbsp;ما تاسو ته دا ټولې خبرې د دې دپاره وکړې چې زما خوشحالى په تاسو کښې وى او چې ستاسو خوشحالى پوره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25584, 'John 15:12', 'John', 15, 12, '&nbsp;دا زما حُکم دے، چې تاسو د يو بل سره مينه کوئ څنګه چې ما تاسو سره مينه کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25585, 'John 15:13', 'John', 15, 13, '&nbsp;د دې نه لويه مينه چا کښې نشته چې يو کس دې د خپل دوست دپاره خپل سر ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25586, 'John 15:14', 'John', 15, 14, '&nbsp;تاسو به هله زما دوستان يئ چې زما په حُکمونو عمل کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25587, 'John 15:15', 'John', 15, 15, '&nbsp;نو زۀ د دې نه پس تاسو ته غلامان نۀ وايم، ځکه چې غلام ته پته نۀ وى چې د هغۀ مالِک څۀ کوى، خو ما تاسو ته دوستان وئيلى دى ځکه چې ما تاسو ته هر هغه څۀ ښکاره کړى دى کوم چې ما د پلار نه اورېدلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25588, 'John 15:16', 'John', 15, 16, '&nbsp;تاسو زۀ غوره کړے نۀ يم خو ما تاسو غوره کړى يئ او ما تاسو مقرر کړئ چې لاړ شئ او مېوه ونيسئ، هغه مېوه چې د تل ده. نو پلار به تاسو ته هر هغه څۀ درکړى څۀ چې تاسو زما په نوم د هغۀ نه وغواړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25589, 'John 15:17', 'John', 15, 17, '&nbsp;دا زما تاسو ته حُکم دے چې د يو بل سره مينه کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25590, 'John 15:18', 'John', 15, 18, '&nbsp;کۀ دُنيا تاسو نه نفرت کوى نو تاسو پوهه شئ چې ستاسو نه اول يې ما نه نفرت کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25591, 'John 15:19', 'John', 15, 19, '&nbsp;کۀ چرې تاسو د دُنيا وے نو دُنيا به تاسو سره د خپلو په شان مينه کړې وه، خو تاسو د دُنيا نۀ يئ. خو ما تاسو د دُنيا نه جدا کړئ نو دغه وجه ده چې دُنيا تاسو نه نفرت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25592, 'John 15:20', 'John', 15, 20, '&nbsp;دا خبرې يادې ساتئ چې کومې ما تاسو ته وکړې، يو نوکر هم د خپل مالِک نه لوئ نۀ وى. نو چې هغوئ زۀ وزورولم نو تاسو به هم وزوروى. کۀ هغوئ زما په کلام عمل وکړى نو ستاسو په کلام به هم عمل وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25593, 'John 15:21', 'John', 15, 21, '&nbsp;خو دوئ به زما د نوم په سبب تاسو سره دا هر څۀ وکړى ځکه چې هغوئ هغه نۀ پېژنى چا چې زۀ رالېږلے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25594, 'John 15:22', 'John', 15, 22, '&nbsp;کۀ زۀ راغلے نۀ وے او دوئ ته مې وئيلے نۀ وے نو دوئ به مجرم نۀ وُو، خو اوس د هغوئ سره د خپلې ګناه څۀ بهانه نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25595, 'John 15:23', 'John', 15, 23, '&nbsp;څوک چې ما نه نفرت کوى هغه زما د پلار نه هم نفرت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25596, 'John 15:24', 'John', 15, 24, '&nbsp;کۀ چرې ما د هغوئ په مينځ کښې داسې کارونه نۀ وے کړے کوم چې بل هيچا هم نۀ دى کړى نو هغوئ به مجرم نۀ وے، خو اوس هغوئ دا وليدل او مونږ پلار زوئ دواړو نه نفرت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25597, 'John 15:25', 'John', 15, 25, '&nbsp;هم د هغوئ په شريعت کښې دا ليکلى دى چې، ”هغوئ ما نه بې‌سببه نفرت وکړو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25598, 'John 15:26', 'John', 15, 26, '&nbsp;خو چې مددګار راشى کوم چې به زۀ تاسو ته د پلار نه درلېږم، يعنې د حقيقت روح چې د پلار نه راوځى، هغه به زما په باب کښې ګواهى ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25599, 'John 15:27', 'John', 15, 27, '&nbsp;تاسو به هم ګواهى ورکوئ ځکه چې تاسو د اول نه ما سره يئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25600, 'John 16:1', 'John', 16, 1, '&nbsp;”ما تاسو ته دا خبرې د دې دپاره وکړې چې تاسو د تيندک خوړلو نه بچ شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');